typedef unsigned int u_int;

enum WavePerturbStageEnum {
    WAVE_PerturbStageNone,
    WAVE_PerturbStageDo,
    WAVE_PerturbStageHold,
    WAVE_PerturbStageCollapse,
    WAVE_PerturbStageWait,
    WAVE_PerturbStageUndo
};

extern float WAVE_ShiftX;
extern float WAVE_MeshMinX;
extern float WAVE_MeshMaxX;
extern int WAVE_PerturbStage;
extern float WAVE_PerturbProgress;

#define WAVE_MESHWIDTH (WAVE_MeshMaxX-WAVE_MeshMinX)

template <int n> struct SplineCoeffs {
    float a[n], b[n], c[n], d[n];
};

template <int n> class WavePerturbStairstepClass {
public:
    char base[448];
    float pulsex[n];
    float pulsexx[n];
    SplineCoeffs<n> pulsecoeffs;
    static const u_int num;
    float WorldToProfile(float worldx);
};

template <int n> const u_int WavePerturbStairstepClass<n>::num = n;

template <int n> inline float SPLINE_Evaluate(const float (&x)[n], const float (&a)[n], const float (&b)[n], const float (&c)[n], const float (&d)[n], u_int num, float xx)
{
    u_int lo = 0, hi = num - 1;
    while (hi - lo >= 2) {
        u_int mid = (lo + hi) >> 1;
        if (x[mid] < xx) lo = mid;
        else hi = mid;
    }
    xx -= x[lo];
    return ((a[lo] * xx + b[lo]) * xx + c[lo]) * xx + d[lo];
}

template <int n> float WavePerturbStairstepClass<n>::WorldToProfile(float worldx)
{
    float profilex;
    static const float &domain = pulsex[num-1];
    float modx = worldx + (WAVE_ShiftX >= 0 ? WAVE_ShiftX : -WAVE_ShiftX) + WAVE_MESHWIDTH;
    modx -= domain * (int) (modx / domain);

    float stairstepx = worldx;
    stairstepx += SPLINE_Evaluate(pulsex, pulsecoeffs.a, pulsecoeffs.b, pulsecoeffs.c, pulsecoeffs.d, num, modx);
    stairstepx -= modx;

    switch (WAVE_PerturbStage) {
    case WAVE_PerturbStageNone:
        profilex = stairstepx;
        break;
    case WAVE_PerturbStageDo:
        profilex = WAVE_PerturbProgress * worldx + (1 - WAVE_PerturbProgress) * stairstepx;
        break;
    case WAVE_PerturbStageUndo:
        profilex = (1 - WAVE_PerturbProgress) * worldx + WAVE_PerturbProgress * stairstepx;
        break;
    default:
        profilex = worldx;
        break;
    }
    return profilex;
}

template class WavePerturbStairstepClass<6>;
